  corpus.push(['x', 'z', 'y', 'tag']);
  corpus.push(['x', 'y', 'z', 'tag']);
  corpus.push(['x', 'y', 'tag', 'z']);
  corpus.push(['p', 'x', 'y', 'tag']); // 4 props, tag in-object
  corpus.push(['p', 'q', 'x', 'y', 'tag']); // 5 props, tag overflows
  corpus.push(['x', 'y', 'tag', 'p', 'q']); // 5 props, p/q overflow

  const muts = {
    noop: () => {},
    addW: (o) => addProp(o, 'w', 'tagged', 'w-val'),
    delTag: (o) => deleteProp(o, 'tag'),
  };

  let total = 0;
  let deopts = 0;
  const problems = [];
  for (const names of corpus) {
    const seq = names.map((n) => [n, keyKinds[n]]);
    for (const [mname, mut] of Object.entries(muts)) {
      resetWorld();

      // Unoptimized reference.
      const refFn = makeFunction();
      const refObj = buildObject(seq);
      const ref = runFunction(refFn, refObj, mut);

      // Same shape, but train + optimize first.
      const optFn = makeFunction();
      runFunction(optFn, buildObject(seq), () => {});
      const ok = optimize(optFn);
      const optObj = buildObject(seq);
      const got = runFunction(optFn, optObj, mut);

      total++;
      if (got.mode === 'deopt') deopts++;
      if (!ok) problems.push(`${names}/${mname}: not optimizable`);
      if (!deepEq(ref.result, got.result)) {
        problems.push(`${names}/${mname}: ${canon(ref.result)} != ${canon(got.result)}`);
      }
      if (got.mode === 'deopt') {
        const canonRef = canon(ref.result);
        const canonGot = canon(got.result);
